<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Private Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071010;--card:#0b1414;--muted:#aebfbf;--accent:#91d7c9;font-family:Inter,system-ui,Segoe UI,Roboto,Arial}
    body{margin:0;background:var(--bg);color:#e8f6f4}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px;background-image:url('assets/img/pattern.svg');background-size:200px}
    nav a{color:#cfeee7;margin-left:18px;text-decoration:none;font-weight:600}
    .container{max-width:1000px;margin:28px auto;padding:0 18px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px}
    h1{margin:0 0 8px 0}
    .small{color:var(--muted)}
    .pill{display:inline-block;padding:8px 10px;border-radius:999px;background:rgba(255,255,255,0.02);font-weight:700;color:var(--accent)}
    .btn{background:var(--accent);color:#03211f;padding:8px 12px;border-radius:8px;border:none;cursor:pointer}
